from pathlib import Path
import subprocess,json,hashlib,tempfile,datetime
store=Path.home()/'repos/touristic-digital-platform.git'
repo='luizanunciostoca/touristic-digital-platform'
base='d979b9813c1ab40b96dee64616b9f7d08a7c0d07'
def run(argv,**kw):
 p=subprocess.run(argv,capture_output=True,**kw)
 if p.returncode: raise RuntimeError('COMMAND_FAILED:'+str(argv[:3]))
 return p.stdout
assert json.loads(run(['gh','api','repos/'+repo+'/commits/main'],text=True))['sha']==base
assert run(['git','--git-dir='+str(store),'rev-parse',base],text=True).strip()==base
root=Path(tempfile.mkdtemp(prefix='tdp-retirement-collector-',dir=Path.home()/'.cache'))
data=json.loads(run(['gh','api','repos/'+repo+'/git/blobs/c4729407898957d76a9063faa5e7647145de2d7b'],text=True))
import base64
req=base64.b64decode(data['content'])
assert hashlib.sha256(req).hexdigest()=='9fa59845419a57b731dc97d06c89813f72ed99df11ee659f18620e2855c35f3f'
(root/'request.json').write_bytes(req)
paths=['tooling','.github/morro-control/claims.json','.github/morro-control/events.ndjson','.morro/changesets/MD-JOURNEY-AUDIT-COVERAGE-ADMISSION-20261031.json']
archive=run(['git','--git-dir='+str(store),'archive',base,*paths])
subprocess.run(['tar','-x','-C',str(root)],input=archive,check=True)
assert not (root/'.git').exists()
runner="""import fs from 'node:fs';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {collectClaimRetirementEvidence} from './tooling/fabric/claim-retirement-proof.mjs';
import {buildClaimRetirement} from './tooling/mdctl/claim-lifecycle.mjs';
const id='MD-JOURNEY-AUDIT-COVERAGE-ADMISSION-20261031';
const request=JSON.parse(fs.readFileSync('request.json','utf8'));
const registry=JSON.parse(fs.readFileSync('.github/morro-control/claims.json','utf8'));
const manifest=JSON.parse(fs.readFileSync('.morro/changesets/'+id+'.json','utf8'));
const ledgerText=fs.readFileSync('.github/morro-control/events.ndjson','utf8');
const token=execFileSync('gh',['auth','token'],{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const evidence=await collectClaimRetirementEvidence(id,registry.claims[id],{repository:request.repository,expectedBaseSha:request.exactBaseSha,token,requestedReason:'VOLUNTARY',decisionRequest:request,canonicalText:ledgerText,canonicalManifest:manifest,retirementBranch:request.retirementBranch});
const result=buildClaimRetirement({registry,ledgerText,manifest,evidence,retirementBaseSha:request.exactBaseSha,retirementBranch:request.retirementBranch,observedAt:evidence.observedAt,requestedReason:'VOLUNTARY',now:Date.now()});
const outputs={'.github/morro-control/claims.json':JSON.stringify(result.registry,null,2)+'\\n','.github/morro-control/events.ndjson':result.ledgerText,['.morro/changesets/'+id+'.json']:JSON.stringify(result.manifest,null,2)+'\\n'};
assert.equal(result.manifest.state,manifest.state);
assert.equal(Object.keys(registry.claims).length-Object.keys(result.registry.claims).length,1);
fs.writeFileSync('generated-output.json',JSON.stringify({kind:'CANONICAL_RETIREMENT_COLLECT_AND_BUILD_OUTPUT',observedAt:evidence.observedAt,baseSha:request.exactBaseSha,branch:request.retirementBranch,evidence,outputs},null,2)+'\\n');
console.log(JSON.stringify({kind:'CANONICAL_RETIREMENT_COLLECT_AND_BUILD',observedAt:evidence.observedAt,reason:evidence.reason,requestDigest:evidence.requestDigest,paths:Object.keys(outputs),state:result.manifest.state,completionClaimed:request.completionClaimed,ownerComment:evidence.ownerDecision.commentId}));
"""
(root/'collector.mjs').write_text(runner)
p=subprocess.run(['node','collector.mjs'],cwd=root,capture_output=True,text=True,timeout=150)
print(p.stdout,flush=True)
if p.returncode:
 print(p.stderr[-6000:],flush=True)
 raise SystemExit(p.returncode)
raw=(root/'generated-output.json').read_bytes()
payload=root/'blob-request.json'
payload.write_text(json.dumps({'content':base64.b64encode(raw).decode(),'encoding':'base64'}))
blob=json.loads(run(['gh','api','--method','POST','repos/'+repo+'/git/blobs','--input',str(payload)],text=True))
print(json.dumps({'generatedOutputBlob':blob['sha'],'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'evidencePath':str(root/'generated-output.json'),'materialWorktreeCreated':False,'branchRefModified':False,'canonicalTransitionIntegrated':False}),flush=True)
TDP_RETIRE
